    CREATE POLICY "DELETE" ON "public"."reimbursementLineDimension" AS PERMISSIVE FOR DELETE TO public USING ((EXISTS (SELECT 1 FROM public."reimbursementLine" l JOIN public."reimbursement" h ON ((h.id = l."reimbursementId") AND (h."companyId" = l."companyId")) WHERE ((l.id = "public"."reimbursementLineDimension"."reimbursementLineId") AND (l."companyId" = "public"."reimbursementLineDimension"."companyId") AND (h.status = 'Draft'::"reimbursementStatus"))) AND ("companyId" = ANY ((SELECT get_companies_with_employee_permission('invoicing.reimbursements_delete'::text))::text[]))));
  

